create_conversation.beforeRequest:
const upsert = (body) => {
  try {
    call({method: 'PUT', url: '/website/' + inputs.websiteId + '/people/profile/' + inputs.email, body});
  } catch (e) {
    if (String(e && e.message || e).includes('status 404')) call({method: 'POST', url: '/website/' + inputs.websiteId + '/people/profile', body});
  }
};
upsert({email: inputs.email, person: {nickname: inputs.username}});
const site = '/website/' + inputs.websiteId + '/conversation';
const session = call({method: 'POST', url: site, body: {}}).data.session_id;
call({method: 'POST', url: site + '/' + session + '/message', body: {type: 'text', from: inputs.messageFrom, origin: 'chat', content: inputs.message}});
call({method: 'PATCH', url: site + '/' + session + '/meta', body: {email: inputs.email, nickname: inputs.username}});
request.url = site + '/' + session;
return request;

create_update_contact.beforeRequest:
const upsert = (body) => {
  try {
    call({method: 'PUT', url: '/website/' + inputs.websiteId + '/people/profile/' + inputs.email, body});
  } catch (e) {
    if (String(e && e.message || e).includes('status 404')) call({method: 'POST', url: '/website/' + inputs.websiteId + '/people/profile', body});
  }
};
const contact = {email: inputs.email, person: {nickname: inputs.name}};
if (inputs.notepad) contact.notepad = inputs.notepad;
if (inputs.phone) contact.person.phone = inputs.phone;
if (inputs.address) contact.person.address = inputs.address;
if (inputs.website) contact.person.website = inputs.website;
if (inputs.company) contact.company = {name: inputs.company};
upsert(contact);
request.url = '/website/' + inputs.websiteId + '/people/profile/' + inputs.email;
return request;

new_contact.beforeRequest:
// The original sends the time with spaces as +.
if (inputs.lastPollTime) request.url += '?filter_date_start=' + encodeURIComponent(new Date(Number(inputs.lastPollTime)).toUTCString()).replace(/%20/g, '+');
return request;

new_contact.afterResponse:
const items = [];
let page = response.data || [];
for (let number = 2; page.length > 0; number++) {
  items.push(...page);
  if (!inputs.lastPollTime) break;
  page = call({method: 'GET', url: '/website/' + inputs.websiteId + '/people/profiles/' + number + '?filter_date_start=' + encodeURIComponent(new Date(Number(inputs.lastPollTime)).toUTCString()).replace(/%20/g, '+'), query: {per_page: '50'}}).data || [];
}
return items;

